parameters.text:
={{ (() => {
  const nombres = {
    REGULAR: 'Regular',
    PREMIUM: 'Premium',
    DIESEL_B5: 'Diésel',
    GLP_AUTOMOTOR: 'GLP',
    GNV: 'GNV'
  };

  const combustible = nombres[$json.fuel_code] || $json.fuel_code;
  const estaciones = Array.isArray($json.stations) ? $json.stations : [];

if ($json.has_location !== true) {
  return `📍 Primero necesito tu ubicación.\n\nEnvía /start y pulsa el botón para compartirla.`;
}

  if (Number($json.stations_found) === 0) {
    return `⛽ ${combustible}\n\nTodavía no tenemos precios oficiales cargados para mostrar estaciones cercanas.`;
  }

  const avisoDemo = estaciones.some(e => e.source === 'DEMO')
    ? '🧪 DATOS DE PRUEBA — No son precios reales\n\n'
    : '';

  return avisoDemo +
    `⛽ Estaciones cercanas — ${combustible}\n\n` +
    estaciones.map((e, i) => {
      const unidad = e.unit === 'PEN_M3' ? 'm³' : 'galón';
      const fecha = e.reported_at
        ? new Date(e.reported_at).toLocaleString('es-PE', {
            timeZone: 'America/Lima',
            dateStyle: 'short',
            timeStyle: 'short'
          })
        : 'No disponible';

      return `${i + 1}. ${e.trade_name}\n` +
        `Precio: S/ ${Number(e.price).toFixed(2)} por ${unidad}\n` +
        `Distancia: ${e.distance_km} km\n` +
        `Dirección: ${e.address || e.district || 'No disponible'}\n` +
        `Actualizado: ${fecha}\n` +
        `Mapa: https://www.google.com/maps?q=${e.latitude},${e.longitude}`;
    }).join('\n\n');
})() }}

