parameters.text:
={{ (() => {
  const opcion = $json.totem_option;
  const items = Array.isArray($json.items) ? $json.items : [];

  if ($json.has_location !== true) {
    return `📍 Primero necesito tu ubicación.\n\nEnvía /start y pulsa el botón para compartirla.`;
  }

  if (Number($json.result_count) === 0) {
    const mensajes = {
      SERVICES: '🚿 Todavía no tenemos servicios verificados cerca de tu ubicación.',
      OFFERS: '🏷️ Todavía no tenemos promociones vigentes cerca de tu ubicación.'
    };

    return `${mensajes[opcion]}\n\nEstamos ampliando la cobertura TOTEM en Lima.`;
  }

  if (opcion === 'SERVICES') {
    return `🚿 Servicios cercanos\n\n` +
      items.map((item, index) => {
        const servicios = Array.isArray(item.services)
          ? item.services.map(servicio => {
              const precio = servicio.price !== null &&
                             servicio.price !== undefined
                ? ` — S/ ${Number(servicio.price).toFixed(2)}`
                : '';

              return `${servicio.icon || '✓'} ${servicio.label}${precio}`;
            }).join('\n')
          : 'Servicios por confirmar';

        return `${index + 1}. ${item.trade_name}\n` +
          `${servicios}\n` +
          `Distancia: ${item.distance_km} km\n` +
          `Dirección: ${item.address || item.district || 'No disponible'}\n` +
          `Mapa: https://www.google.com/maps?q=${item.latitude},${item.longitude}`;
      }).join('\n\n');
  }

  return `🏷️ Promociones\n\n` +
    items.map((item, index) => {
      const descuento = item.discount_percent !== null &&
                        item.discount_percent !== undefined
        ? `Descuento: ${Number(item.discount_percent).toFixed(0)}%\n`
        : '';

      const precio = item.promotional_price !== null &&
                     item.promotional_price !== undefined
        ? `Precio promocional: S/ ${Number(item.promotional_price).toFixed(2)}\n`
        : '';

      const codigo = item.promo_code
        ? `Código promocional: ${item.promo_code}\n`
        : '';

      const vigencia = item.valid_until
        ? `Válido hasta: ${new Date(item.valid_until).toLocaleDateString('es-PE', {
            timeZone: 'America/Lima'
          })}\n`
        : '';

      const condiciones = item.terms_and_conditions
        ? `Condiciones: ${item.terms_and_conditions}\n`
        : '';

      return `${index + 1}. ${item.offer_category_icon || '🏷️'} ${item.title}\n` +
        `${item.description || ''}\n` +
        `${descuento}${precio}${codigo}${vigencia}${condiciones}` +
        `Estación: ${item.trade_name}\n` +
        `Distancia: ${item.distance_km} km\n` +
        `Mapa: https://www.google.com/maps?q=${item.latitude},${item.longitude}`;
    }).join('\n\n');
})() }}

