parameters.textBody:
=={{ (() => {
  const nombres = { REGULAR: 'Regular', PREMIUM: 'Premium', DIESEL_B5: 'Diésel', GLP_AUTOMOTOR: 'GLP', GNV: 'GNV' };
  const combustible = nombres[$json.fuel_code] || $json.fuel_code;
  const estaciones = Array.isArray($json.stations) ? $json.stations : [];

  if ($json.has_location !== true) {
    return '📍 Primero necesito tu ubicación. Escribe cualquier mensaje y elige Buscar combustible de nuevo.';
  }
  if (Number($json.stations_found) === 0) {
    return `⛽ ${combustible}\n\nTodavía no tenemos precios cargados para mostrar estaciones cercanas.`;
  }

  const ACRONIMOS = ['GLP','GNV','BCP','CMR','LATAM PASS','LATAM','AVA CASH','AVA','SHELL HELIX','REPSHOP','REPSOL','PRIMAX','PECSA','SS.HH.','S.A.','24 HRS'];
  const conAcronimos = (s) => {
    ACRONIMOS.forEach(a => {
      const re = new RegExp('\\b' + a.toLowerCase().replace(/\./g, '\\.') + '\\b', 'gi');
      s = s.replace(re, a);
    });
    return s;
  };
  const clausula = (txt) => txt ? conAcronimos(txt.trim().toLowerCase().replace(/\.+$/, '')) : '';
  const charla = (e) => {
    const partes = [];
    if (e.field_comments) partes.push(clausula(e.field_comments));
    if (e.nearby_businesses) partes.push('cerca tienes ' + clausula(e.nearby_businesses));
    if (e.other_notes) partes.push(clausula(e.other_notes));
    if (e.loyalty_program) partes.push('acumula puntos con ' + clausula(e.loyalty_program));
    if (!partes.length) return '';
    let texto = partes.join('. ') + '.';
    texto = texto.charAt(0).toUpperCase() + texto.slice(1);
    return `\n💬 ${texto}`;
  };

  return `⛽ Estaciones cercanas — ${combustible}\n\n` +
    estaciones.map((e, i) => {
      const unidad = e.unit === 'PEN_M3' ? 'm³' : 'galón';
      const bandera = e.brand ? ` (${e.brand})` : '';
      return `${i + 1}. ${e.trade_name}${bandera}\n` +
        `Precio: S/ ${Number(e.price).toFixed(2)} por ${unidad}\n` +
        `Distancia: ${e.distance_km} km\n` +
        `Dirección: ${e.address || e.district || 'No disponible'}\n` +
        `Estado: ${e.estado_vigencia}` +
        charla(e) + `\n` +
        `Mapa: https://www.google.com/maps?q=${e.latitude},${e.longitude}`;
    }).join('\n\n') +
    '\n\n—\nEscribe cualquier mensaje para volver al menú, o comparte tu ubicación de nuevo para buscar otro combustible.';
})() }}

