={{ JSON.stringify((() => {
  const nombres = { REGULAR: 'Regular', PREMIUM: 'Premium', DIESEL_B5: 'Diésel', GLP_AUTOMOTOR: 'GLP', GNV: 'GNV' };
  const combustible = nombres[$json.fuel_code] || $json.fuel_code;
  const todas = Array.isArray($json.stations) ? $json.stations : [];
  const pagina = $json.requested_page === '2' ? 2 : 1;
  const estaciones = pagina === 1 ? todas.slice(0, 3) : todas.slice(3, 6);
  const offset = pagina === 1 ? 0 : 3;

  let texto;
  if ($json.has_location !== true) {
    texto = '📍 Primero necesito tu ubicación. Escribe cualquier mensaje y elige Buscar combustible de nuevo.';
  } else if (Number($json.stations_found) === 0) {
    texto = `⛽ ${combustible}: todavía no tenemos precios cargados cerca de ti.`;
  } else {
    const encabezado = pagina === 1 ? `⛽ Precios de ${combustible} cerca de ti:\n` : `⛽ Más precios de ${combustible}:\n`;
    texto = encabezado + estaciones.map((e, i) => {
      const unidad = e.unit === 'PEN_M3' ? 'm³' : 'galón';
      const bandera = e.brand ? ` (${e.brand})` : '';
      return `${offset + i + 1}. ${e.trade_name}${bandera}: S/ ${Number(e.price).toFixed(2)} por ${unidad}`;
    }).join('\n');
  }

  const hayMas = pagina === 1 && todas.length > 3;
  const hayResultados = $json.has_location === true && Number($json.stations_found) > 0;
  const buttons = [];
  if (hayMas) buttons.push({ type: 'reply', reply: { id: `ver_mas:${$json.fuel_code}`, title: 'Ver 3 más' } });
  if (hayResultados) buttons.push({ type: 'reply', reply: { id: `ver_detalles:${$json.fuel_code}:${pagina}`, title: 'Ver detalles' } });

  if (buttons.length === 0) {
    return {
      messaging_product: 'whatsapp',
      to: $json.whatsapp_id,
      type: 'text',
      text: { body: texto }
    };
  }

  return {
    messaging_product: 'whatsapp',
    to: $json.whatsapp_id,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: texto },
      action: { buttons }
    }
  };
})()) }}

