const resp = $json;
const orig = $('PG - Leer direcciones pendientes').item.json;
const status = resp.status || 'NO_RESPONSE';
let lat = null, lng = null, formatted = null, locationType = null;

if (status === 'OK' && Array.isArray(resp.results) && resp.results.length) {
  const r = resp.results[0];
  lat = r.geometry?.location?.lat ?? null;
  lng = r.geometry?.location?.lng ?? null;
  formatted = r.formatted_address ?? null;
  locationType = r.geometry?.location_type ?? null;
}

return {
  registro_hidrocarburos: orig.registro_hidrocarburos,
  full_address: orig.full_address,
  geocode_status: status + (locationType ? (':' + locationType) : ''),
  latitude: lat,
  longitude: lng,
  formatted_address: formatted
};

