=={{ (() => {
  const e = $json;
  if (!e.nombre_totem) {
    return '⚠️ No encontramos esa estación. Escribe cualquier mensaje para volver al menú.';
  }

  const precios = Array.isArray(e.precios) ? e.precios : [];
  const ORDEN_FUEL = ['REGULAR', 'PREMIUM', 'DIESEL_B5', 'GLP_AUTOMOTOR', 'GNV'];
  const lineasPrecio = ORDEN_FUEL
    .map(code => precios.find(p => p.fuel_code === code))
    .filter(Boolean)
    .map(p => {
      const sufijo = p.unit === 'PEN_M3' ? '/m³' : (p.unit === 'PEN_GALLON' ? '/gal' : '');
      return `${p.label}: S/ ${Number(p.price).toFixed(2)} ${sufijo}`;
    });

  const ACRONIMOS = ['GLP','GNV','BCP','CMR','LATAM PASS','LATAM','AVA CASH','AVA','SHELL HELIX','REPSHOP','REPSOL','PRIMAX','PECSA','SS.HH.','S.A.','24 HRS'];
  const conAcronimos = (s) => {
    ACRONIMOS.forEach(a => {
      const re = new RegExp('\\b' + a.toLowerCase().replace(/\./g, '\\.') + '\\b', 'gi');
      s = s.replace(re, a);
    });
    return s;
  };
  const clausula = (txt) => txt ? conAcronimos(txt.trim().toLowerCase().replace(/\.+$/, '')) : '';
  const charlaTxt = (() => {
    const partes = [];
    if (e.field_comments) partes.push(clausula(e.field_comments));
    if (e.nearby_businesses) partes.push('cerca tienes ' + clausula(e.nearby_businesses));
    if (e.other_notes) partes.push(clausula(e.other_notes));
    if (e.loyalty_program) partes.push('acumula puntos con ' + clausula(e.loyalty_program));
    if (!partes.length) return '';
    let texto = partes.join('. ') + '.';
    texto = texto.charAt(0).toUpperCase() + texto.slice(1);
    return `\n💬 ${texto}\n`;
  })();

  const MESES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  const formatExpira = (iso) => {
    if (!iso) return '';
    const d = new Date(iso);
    const partes = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Lima', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d);
    const get = (t) => partes.find(p => p.type === t).value;
    return ` (vence ${get('day')}-${MESES[parseInt(get('month'), 10) - 1]}-${get('year')})`;
  };
  const servicios = Array.isArray(e.servicios) ? e.servicios : [];
  const lineasServicios = servicios.map(s => `${s.label}${formatExpira(s.expires_at)}`);
  const bloqueServicios = lineasServicios.length ? `\n\n🔎 Servicios\n${lineasServicios.join('\n')}` : '';

  const bandera = e.brand ? `\n🏁 ${e.brand}` : '';
  const distancia = (e.distance_km !== null && e.distance_km !== undefined) ? `\nA ${e.distance_km} km de tu ubicación` : '';

  return `${e.nombre_totem}${bandera}\n\n` +
    `⛽ Precios\n${lineasPrecio.join('\n')}\n\n` +
    `📍 ${e.address || e.district || 'No disponible'}${distancia}` +
    bloqueServicios +
    charlaTxt +
    `\n\n🌐 Ver en Google Maps: https://www.google.com/maps?q=${e.latitude},${e.longitude}` +
    '\n\nSi deseas buscar otra cosa escribe la palabra MENU';
})() }}

