const resp = $json;
const orig = $('PG - Leer PILOT_01').item.json;
const googleStatus = String(resp.status || 'NO_RESPONSE');
const result = Array.isArray(resp.results) ? resp.results[0] : null;

let latitude = null;
let longitude = null;
let formattedAddress = null;
let locationType = null;
let queueStatus = 'ERROR';
let lastError = resp.error_message || null;

if (googleStatus === 'OK' && result) {
  latitude = Number(result.geometry?.location?.lat);
  longitude = Number(result.geometry?.location?.lng);
  formattedAddress = result.formatted_address || null;
  locationType = result.geometry?.location_type || null;

  const coordinatesAreValid =
    Number.isFinite(latitude) &&
    Number.isFinite(longitude) &&
    latitude >= -19 &&
    latitude <= 0 &&
    longitude >= -82 &&
    longitude <= -68;

  if (!coordinatesAreValid) {
    queueStatus = 'REVIEW';
    lastError = 'COORDINATES_OUTSIDE_PERU_OR_INVALID';
  } else if (['ROOFTOP', 'RANGE_INTERPOLATED', 'GEOMETRIC_CENTER'].includes(locationType)) {
    queueStatus = 'SUCCESS';
  } else {
    queueStatus = 'REVIEW';
